    async fn resolve_model(
        &mut self,
        project: &Project,
        model: &str,
        thinking: &str,
    ) -> Result<ModelChoice, ModelError> {
        let requested = if model.is_empty() {
            project
                .model
                .as_deref()
                .or(self.agent_model.as_deref())
                .unwrap_or("")
        } else {
            model
